import{_ as a,o as e,c as r,ag as t}from"./chunks/framework.CYCRomDB.js";const p=JSON.parse('{"title":"AI 會取代工程師嗎?","description":"AI 會取代工程師嗎? 目前我認為 AI 的主要使用對象就是工程師!! 目前多數人或社會媒體也搶著宣稱自己的職業、工作會被取代 但現在進行中，被取代的對象，極有可能就是軟體工程師，而且軟體工程師也正透過 AI 完成自己的工作!!","frontmatter":{"title":"AI 會取代工程師嗎?","date":"2026-05-06T00:00:00.000Z","updated":"2026-06-10T00:00:00.000Z","description":"AI 會取代工程師嗎? 目前我認為 AI 的主要使用對象就是工程師!! 目前多數人或社會媒體也搶著宣稱自己的職業、工作會被取代 但現在進行中，被取代的對象，極有可能就是軟體工程師，而且軟體工程師也正透過 AI 完成自己的工作!!","author":"Cola","tags":["Experience"],"keywords":["Experience","php","seo"],"readingTime":"7 min read","readingMinutes":7,"permalink":"/will-ai-replace-programmers","slug":"will-ai-replace-programmers","issueId":20,"githubUrl":"https://github.com/workxplay/cscolabear.github.io/issues/20"},"headers":[],"relativePath":"will-ai-replace-programmers.md","filePath":"posts/will-ai-replace-programmers.md","lastUpdated":null}');const i=a({name:"will-ai-replace-programmers.md"},[["render",function(a,p,i,o,s,h){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="ai-會取代工程師嗎" tabindex="-1">AI 會取代工程師嗎? <a class="header-anchor" href="#ai-會取代工程師嗎">#</a></h1><p><img src="https://github.com/user-attachments/assets/dc8596c2-b12f-40a7-bd5c-9d21d75a0c22" alt="Image" loading="lazy"></p><p>AI 會取代工程師嗎?</p><p>目前我認為 AI 的主要使用對象就是工程師!! 目前多數人或社會媒體也搶著宣稱自己的職業、工作會被取代 但現在進行中，被取代的對象，極有可能就是軟體工程師，而且軟體工程師也正透過 AI 完成自己的工作!!</p><p>最近社會上常出現的議題：□□工作將被 AI 取代</p><p>撰文至今，頻繁使用 AI 的人，應該都覺得；最快、最先會被取代的應該是軟體工程師吧 XD</p><h2 id="ai-會取代工程師嗎-1" tabindex="-1">AI 會取代工程師嗎? <a class="header-anchor" href="#ai-會取代工程師嗎-1">#</a></h2><p>我認為，答案是會被取代，但也不會!</p><p>現在，因為 AI 的關係... 軟體、程式開發的短期門檻已經降低到，使用者識字即可的程度 只要你會打字、聊天，AI 都能、都有機會產出極度 &quot;客制化&quot; 的應用軟體</p><p>(但長期維護的成本卻可能上升!)</p><h2 id="ai-的出現與資深工程師的心境" tabindex="-1">AI 的出現與資深工程師的心境 <a class="header-anchor" href="#ai-的出現與資深工程師的心境">#</a></h2><p>我，資深工程師面對 AI 的感覺? 被取代? 更提升?</p><p>其實我自己是喜憂參半 被取代的感覺倒是沒有那麼重，反而是覺得，需要調整工作模式和流程~</p><h3 id="開心的部份" tabindex="-1">開心的部份 <a class="header-anchor" href="#開心的部份">#</a></h3><p>期待學習新的東西，不論是學 AI 或是透過 AI 學東西 都可以透過 AI 更快實踐、更快推進 Side Project 或是小工具、串接更多服務等</p><h3 id="擔心的部份" tabindex="-1">擔心的部份 <a class="header-anchor" href="#擔心的部份">#</a></h3><p>猴子更多 在寫程式方面的門檻變低，更容易收到 &quot;這不是很容易嗎?&quot;、&quot;用 AI 都很快&quot; 的發言</p><p>(難易度與開發速度快慢的問題，應該要分開討論)</p><p>使用 AI 的確可以讓門外漢，產出屬於自己的的產品，但，他也相對的可怕!! 加速劣幣驅逐良幣的市場</p><p>試想，病患對著醫生說：『我查過 AI 了，這個需要開刀! 醫生你講的是錯的!!!』 現實中，醫生可能也會犯錯，但 AI 不是每次都正確!! 而且 AI 並不會負責任 你會想請哪一位、什麼角色，替你看病、治病呢? 並不會因為使用了 AI，你就可以自稱，『我很會開刀』😏</p><p>AI 他只是降低，你的入門門檻而已 <strong>能不能取代工程師，全看你的需求和風險接受度</strong></p><h3 id="老闆的心態" tabindex="-1">老闆的心態? <a class="header-anchor" href="#老闆的心態">#</a></h3><p>我好奇 目前市場上有純靠 AI，生成產品賺錢的嗎?</p><p>AI 目前的最佳實踐一直改變，以日或週為單位 而且週期一直加快 今天你透過 AI 推出的產品，明天就變成 AI 大廠的小工具</p><p>目前，多數的老闆們都是擁抱 AI 但方式大有不同... 老闆不斷的要求員工使用 AI, 而自己說不出個什麼有關 AI 的內容, 常常只看著 『網紅們的一發成功影片』就誤解了 AI 的使用 誤解，幾個字，幾斷話，就能生成 Facebook, Google 等級的網站或是好萊塢等級的影片... 不考慮 token 花費問題，更甚忽略了 &quot;對話&quot; 所需的時間，其實還是有一定的成本存在</p><p>在工程師開發 &quot;技能&quot; 之前 &quot;選擇&quot; 與 &quot;判斷&quot;，其實是更有價值的動作</p><p>『AI 可以提升工程師，也能取代不使用 AI 的工程師』</p><p>當然也有的公司老闆，提供金錢輔助讓員工自行嘗試，改善、優化自己的工作流程; 自己身先士卒吐出了很多成功、失敗的成果</p><p>AI 會取代工程師嗎?</p><p>AI 的導入如同，你小時候學習用電腦或學習用手機 有的人，使用的好，有的人不太順手... 如同，最初的 <a href="https://en.wikipedia.org/wiki/Ray_Tomlinson" target="_blank" rel="noreferrer">email</a> 的出現 全世界都預期將會減少工作、增加效率，縮短工時 但， 實際上，隨著 email 的普及，每個人的工作量只有增加，沒有減少 😂 AI 的出現，只是另一種工業革命 而且他落地的速度非常快</p><h3 id="最後" tabindex="-1">最後 <a class="header-anchor" href="#最後">#</a></h3><p>AI 會取代工程師嗎? 答案很難說..</p><p>軟體的價值在維護，不完全是速度 如果要拼速度，其實就是一種技術債 (trade off)</p><p>但，我認為可以不斷的在公司內部推出小工具、小作品 可以確保 &quot;可靠性、穩定性&quot;；當然，如果是新創公司在試水溫沒有客戶、沒品牌包伏，怎麼玩都沒問題。</p><p>AI 的出現，是好是壞目前還看不出來 但他一定會有些地位和改善 (而且週期極快) 除了使用 AI，我們是不是也要注意自己變笨了呢? (大腦外包是好事嗎?)</p><p>藤子・F・不二雄 短篇集 <a href="https://ja.wikipedia.org/wiki/%E3%81%BF%E3%81%8D%E3%81%8A%E3%81%A8%E3%83%9F%E3%82%AD%E3%82%AA" target="_blank" rel="noreferrer">Mikio to Mikio (みきおとミキオ)</a>，中有個橋段..</p><img loading="lazy" width="378" height="678" alt="fuj-f-Mikio to Mikio" src="https://github.com/user-attachments/assets/3bbcdbdb-d999-4471-b1d1-a916bc28b0c6"><p>這個像大雄的傢伙，透過紙筆手算的方式，計算出連未來人也不會的計算題 工具愈聰明，你愈笨</p><p>記得 <strong>AI 是工具，善用、學習工具才是正道</strong> 大老闆會請司機代為開車，也會請廚師煮飯；但不代表，他們不會開車、用刀</p><hr><div class="github-discussion"><a href="https://github.com/workxplay/cscolabear.github.io/issues/20" target="_blank" rel="noopener noreferrer"> 💬 在 GitHub 上討論這篇文章 </a></div>',41)])])}]]);export{p as __pageData,i as default};
